-- TIETOMEDIA: learn-paketit 9 ikivihreälle visalle (2.8.2026)
-- Faktantarkistettu web-lähteistä 2.8.2026; ajettu tuotantoon MCP:llä.
update quizzes set learn = $LJ${"intro": "Suomi tunnetaan tuhansien järvien maana, mutta harva tietää, miten tarkkaan järvemme on oikeasti laskettu – ja kuka urakan aikanaan teki. Jääkausi jätti jälkeensä matalien altaiden labyrintin, jonka mittasuhteet yllättävät tilastoja tuntevankin.", "heading": "Nyt tiedät nämä Suomen järvistä", "key_facts": [{"k": "Kuinka suuri osa Suomesta on järviä?", "v": "Järvet peittävät 9,4 prosenttia Suomen pinta-alasta – lähes joka kymmenes neliökilometri on järveä.", "qi": 0}, {"k": "Miksi Suomen järvet ovat matalia?", "v": "Mannerjäätikkö hioi maankamaran loivaksi, joten järvien keskisyvyys on vain 7 metriä.", "qi": 1}, {"k": "Milloin Suomen järvet laskettiin?", "v": "Professori Mikko Raatikaisen johtaman järvilaskennan tulokset julkistettiin kesäkuussa 1985: vähintään viiden aarin järviä ja lampia löytyi 187 888.", "qi": 2}, {"k": "Mikä on Suomen suurin järvi?", "v": "Suur-Saimaa, noin 4 380 km². Inarijärvi ja Päijänne kilpailevat kakkossijasta vain kolmen neliökilometrin erolla.", "qi": 3}, {"k": "Montako yli hehtaarin järveä Suomessa on?", "v": "Noin 56 000. Kun mukaan lasketaan vähintään viiden aarin lammet, määrä nousee lähes 190 000:een.", "qi": 6}, {"k": "Miten Vuoksi syntyi?", "v": "Maankamaran kallistuttua jääkauden jälkeen Saimaa puhkaisi itselleen uuden lasku-uoman noin 5 700 vuotta sitten.", "qi": 7}, {"k": "Keskittyykö järviala suurille järville?", "v": "Kyllä: 309 yli kymmenen neliökilometrin järveä kattaa noin 65 prosenttia koko Suomen järvialasta.", "qi": 9}], "title": "Suomen järvet pähkinänkuoressa", "sections": [{"h": "Jääkauden muovaamat altaat", "p": ["Suomen järvialtaat syntyivät, kun mannerjäätikkö hioi kallioperää ja jätti jälkeensä loivapiirteisen, painanteita täynnä olevan maan. Siksi järvemme ovat matalia: keskisyvyys on vain seitsemän metriä, ja vettä kaikissa järvissä on yhteensä noin 235 kuutiokilometriä.", "Maankohoaminen muokkaa vesistöjä yhä. Kun maankamara kallistui jääkauden jälkeen, Saimaan vedet puhkaisivat noin 5 700 vuotta sitten uuden lasku-uoman, Vuoksen, joka vie vedet kohti Laatokkaa."]}, {"h": "Suuri järvilaskenta", "p": ["Kuinka monta järveä Suomessa oikeastaan on? Kysymykseen tartuttiin tosissaan 1980-luvulla, kun Jyväskylän yliopiston biologian professori Mikko Raatikainen käynnisti koko maan kattavan järvilaskennan. Tulokset julkistettiin kesäkuussa 1985: vähintään viiden aarin kokoisia järviä ja lampia löytyi 187 888.", "Laskenta paljasti myös, missä järvet ovat tiheimmässä. Pelkältä Näätämöjoen vesistöalueelta Inarijärven itäpuolelta löytyi 21 800 järveä ja lampea. Yli hehtaarin kokoisia järviä koko maassa on noin 56 000."]}, {"h": "Saimaasta Inariin", "p": ["Suomen suurin järvi on Suur-Saimaa, pinta-alaltaan noin 4 380 neliökilometriä. Luku riippuu tosin määritelmästä: tiukimmillaan Saimaaksi lasketaan vain vajaan 1 400 neliökilometrin ydinallas, mutta yleensä suurjärveen luetaan koko yhtenäinen altaiden sokkelo.", "Seuraavat sijat menevät niukasti Inarijärvelle (1 084 km²) ja Päijänteelle (1 081 km²); Oulujärvi on neljäs. Suurin tekojärvi on Kemijoen latvavesille padottu Lokka. Järviala on muutenkin keskittynyt isoille järville: 309 yli kymmenen neliökilometrin järveä kattaa noin 65 prosenttia koko järvialasta."]}, {"h": "Tuhansien järvien maine", "p": ["Sanonta tuhansien järvien maasta juontaa Maamme-lauluun: Runebergin runon suomennoksessa lauletaan 'maa tuhatjärvinen'. Ilmaus löytyy harvemmin lauletusta kymmenennestä säkeistöstä – koko runossa säkeistöjä on yksitoista.", "Todellisuus ylittää runon moninkertaisesti, mutta vesimäärältään Suomi ei silti ole jättiläinen: pelkästään Laatokassa on lähes neljä kertaa enemmän vettä kuin kaikissa Suomen järvissä yhteensä. Matalat järvemme peittävät silti 9,4 prosenttia maan pinta-alasta."]}], "faq": [{"q": "Kuinka monta järveä Suomessa on?", "a": "Määritelmästä riippuen: vähintään viiden aarin järviä ja lampia laskettiin 187 888, yli hehtaarin järviä on noin 56 000."}, {"q": "Mikä on Suomen suurin tekojärvi?", "a": "Lokan tekojärvi Kemijoen vesistön latvoilla; sen säännöstely aloitettiin vuonna 1967."}, {"q": "Miksi Suomessa on niin paljon järviä?", "a": "Jääkausi kaiversi kallioperään painanteita ja jätti moreenipatoja, joihin sulamisvedet kerääntyivät. Maankohoaminen on sen jälkeen muokannut järvien lasku-uomia."}, {"q": "Kuinka paljon vettä Suomen järvissä on?", "a": "Yhteensä noin 235 kuutiokilometriä, ja määrä vaihtelee sateisuuden mukaan kymmeniä miljardeja tonneja vuodessa."}], "sources": [{"name": "Vesi.fi: Kuinka paljon järvissä on vettä?", "url": "https://www.vesi.fi/vesitieto/kuinka-paljon-jarvissa-on-vetta/"}, {"name": "Wikipedia: Suomen järvet", "url": "https://fi.wikipedia.org/wiki/Suomen_j%C3%A4rvet"}, {"name": "Järvi-meriwiki: Saimaa", "url": "https://www.jarviwiki.fi/wiki/Saimaa"}, {"name": "Vesi.fi: Kemijoen vesistöalueen säännöstely", "url": "https://www.vesi.fi/teemasivu/vesistojen-saannostely/kemijoen-vesistoalueen-saannostely/"}], "last_reviewed": "2026-08-02"}$LJ$::jsonb where slug = 'suomen-jarvet';
update quizzes set learn = $LJ${"intro": "Suomen joet ovat järvien varjoon jäänyt vesistöjen selkäranka: ne kuljettavat sulamisvedet Lapin tuntureilta ja Pohjanmaan lakeuksilta mereen. Jokien pituuksien vertailu on yllättävän kinkkistä, sillä mittaustapa ratkaisee usein koko sijoituksen.", "heading": "Nyt tiedät nämä Suomen joista", "key_facts": [{"k": "Mikä on Suomen pisin joki?", "v": "Kemijoki, noin 550 km. Sen vesistöalue kattaa noin puolet Lapista.", "qi": 0}, {"k": "Mikä on Suomen toiseksi pisin joki?", "v": "Iijoki, jonka pääuoma virtaa noin 370 km Kuusamon Iijärvestä Perämereen.", "qi": 1}, {"k": "Mikä on Suomen pisin sivujoki?", "v": "Kemijokeen laskeva Ounasjoki, noin 300 km. Se on suojeltu voimalaitosrakentamiselta erityislailla vuodesta 1983.", "qi": 2}, {"k": "Mistä Ounasjoki alkaa?", "v": "Ounasjärvestä Enontekiöltä; se yhtyy Kemijokeen Rovaniemellä.", "qi": 3}, {"k": "Mikä on Pohjanmaan pisimpiä jokia?", "v": "Kyrönjoki, 127 km. Tulvaherkkä joki laskee Pohjanlahteen Vaasan koillispuolella.", "qi": 4}, {"k": "Mikä joki tunnetaan romaanisarjasta?", "v": "Iijoki – Kalle Päätalon Iijoki-sarja kasvoi 26-osaiseksi.", "qi": 6}, {"k": "Mikä on pisin Suomenlahteen laskeva joki?", "v": "Kymijoki, 204 km. Se laskee mereen useana suuhaarana.", "qi": 9}], "title": "Suomen joet pähkinänkuoressa", "sections": [{"h": "Lapin suuret virrat", "p": ["Suomen jokien kuningas on Kemijoki: noin 550 kilometriä pitkä pääuoma ja vesistöalue, joka kattaa noin puolet Lapin maakunnasta. Joki on valjastettu tehokkaasti – vesistössä on 21 voimalaitosta, jotka tuottavat noin kolmanneksen Suomen vesivoimasta.", "Kemijoen suurin sivujoki Ounasjoki on toista maata. Se virtaa noin 300 kilometriä Enontekiön Ounasjärvestä Rovaniemelle vapaana, sillä erillinen laki on suojannut sen voimalaitosrakentamiselta vuodesta 1983."]}, {"h": "Mittaustapa ratkaisee", "p": ["Jokien pituusvertailu on tulkintalaji. Tornionjoen pituus lasketaan Suomen tilastoissa yleensä vasta Muonionjoen yhtymäkohdasta, minkä vuoksi noin 230-kilometrinen Muonionjoki ja Tornionjoki muodostavat yhdessä pitkän rajajoen mutta jäävät listoilla Kemijoen taakse.", "Toiseksi pisin on siten Iijoki, jonka pääuoma virtaa noin 370 kilometriä Kuusamon Iijärvestä Perämereen. Kirjallisuudessa Iijoki on ykkönen: Kalle Päätalon 26-osainen Iijoki-sarja teki joesta käsitteen."]}, {"h": "Pohjanmaan lakeuksien joet", "p": ["Pohjanmaalla joet virtaavat tasaisen ja vähäjärvisen maan halki, mikä tekee niistä tulvaherkkiä. Kyrönjoki on 127 kilometrillään alueen pisimpiä – pidempi kuin tunnetummat Kokemäenjoki ja Vantaanjoki – ja sen kevättulvia hillitään säännöstelyllä.", "Perämereen laskeva Simojoki on toisenlainen tapaus: 193 kilometriä kirkasvetistä uomaa Simojärvestä mereen. Se tunnetaan yhtenä harvoista suurista lohijoistamme, joiden pääuomaa ei ole padottu."]}, {"h": "Etelän pitkät joet", "p": ["Etelärannikolle laskevista joista pisin on Kymijoki, 204 kilometriä. Se purkaa laajan vesistönsä vedet Suomenlahteen useana suuhaarana.", "Varsinais-Suomessa Paimionjoki yltää noin 110 kilometriin, mutta vain noin 70 kilometriä siitä on varsinaista jokiuomaa – loppu on latvaosien järviketjua. Pituusluvut kertovatkin aina myös siitä, mitä uomaan on päätetty laskea mukaan."]}], "faq": [{"q": "Onko Tornionjoki Suomen pisin joki?", "a": "Ei tilastoissa: sen pituus lasketaan yleensä vasta Muonionjoen yhtymäkohdasta, joten pisin on Kemijoki, noin 550 km."}, {"q": "Mitkä Suomen suurista joista ovat säilyneet vapaina?", "a": "Ounasjoki on suojeltu voimalaitosrakentamiselta lailla vuodesta 1983, ja esimerkiksi kirkasvetisen Simojoen pääuoma virtaa patoamattomana."}, {"q": "Miksi Kemijoki on niin tärkeä vesivoimalle?", "a": "Sen vesistössä on 21 voimalaitosta, joiden osuus on noin kolmannes Suomen vesivoiman tuotannosta."}, {"q": "Kuinka pitkä Muonionjoki on?", "a": "Noin 230 km. Se on Tornionjoen suurin sivujoki ja muodostaa Suomen ja Ruotsin rajaa."}], "sources": [{"name": "Suomen luonnonsuojeluliitto: Vapauta Kemijoki", "url": "https://www.sll.fi/opi-lisaa/vedet/vapauta-virrat/vapauta-kemijoki/"}, {"name": "Vesi.fi: Kemijoen vesistöalueen säännöstely", "url": "https://www.vesi.fi/teemasivu/vesistojen-saannostely/kemijoen-vesistoalueen-saannostely/"}, {"name": "Vesi.fi: Kyrönjoen vesistöalueen säännöstely", "url": "https://www.vesi.fi/teemasivu/vesistojen-saannostely/kyronjoen-vesistoalueen-saannostely/"}, {"name": "Järvi-meriwiki: Kymijoki", "url": "https://www.jarviwiki.fi/wiki/Kymijoki"}, {"name": "Paimionjoki-yhdistys: Paimionjoki", "url": "https://www.paimionjoki.fi/paimionjoki"}], "last_reviewed": "2026-08-02"}$LJ$::jsonb where slug = 'suomen-joet';
update quizzes set learn = $LJ${"intro": "Järvi voi olla suolainen kuin meri, syvempi kuin moni merenlahti ja isompi kuin kokonainen valtio. Suurimpien järvien joukossa on ikivanhoja hautavajoamia, jääkauden kaivertamia altaita ja vuoristoylängöille syntyneitä vesiä usealla mantereella.", "heading": "Nyt tiedät nämä maailman suurimmista järvistä", "key_facts": [{"k": "Mikä on maailman suurin järvi?", "v": "Kaspianmeri – suolainen sisävesi Euroopan ja Aasian rajalla, jonka rannoilla on viisi valtiota.", "qi": 0}, {"k": "Kuinka suuri Kaspianmeri on?", "v": "Noin 371 000 km² eli enemmän kuin koko Suomen pinta-ala (338 000 km²).", "qi": 1}, {"k": "Mikä on maailman syvin järvi?", "v": "Baikaljärvi: yli 1 600 metriä syvä, maailman vanhin ja tilavuudeltaan suurin makean veden järvi.", "qi": 3}, {"k": "Mikä on pinta-alaltaan suurin makean veden järvi?", "v": "Yläjärvi eli Lake Superior Pohjois-Amerikassa, noin 82 100 km².", "qi": 7}, {"k": "Mikä on Afrikan suurin järvi?", "v": "Victoriajärvi, noin 69 500 km² – makean veden järvistä toiseksi suurin heti Yläjärven jälkeen.", "qi": 4}, {"k": "Mikä on Euroopan suurin järvi?", "v": "Venäjän Laatokka, noin 17 600 km². Kakkosena on niin ikään venäläinen Ääninen.", "qi": 2}, {"k": "Missä on maapallon matalin maanpinnan kohta?", "v": "Kuolleenmeren rannalla, yli 400 metriä merenpinnan alapuolella – ja järven pinta laskee yhä.", "qi": 9}], "title": "Maailman suurimmat järvet pähkinänkuoressa", "sections": [{"h": "Sisämeri ilman merta", "p": ["Suurin kaikista on Kaspianmeri, noin 371 000 neliökilometrin suolainen sisävesi Euroopan ja Aasian rajalla – pinta-alaltaan suurempi kuin koko Suomi. Sen rannoilla on viisi valtiota, ja pohjoisesta etelään matkaa kertyy lähes 1 200 kilometriä.", "Jättiläinen on kuitenkin kutistumassa: satelliittimittausten mukaan Kaspianmeren pinta on laskenut 1990-luvun puolivälistä lähtien, ja mallit ennustavat laskun jatkuvan tällä vuosisadalla."]}, {"h": "Syvin, vanhin, vetisin", "p": ["Siperian Baikaljärvi on ennätysten järvi. Se on yli 1 600 metrin syvyydellään maailman syvin järvi ja arviolta 20–25 miljoonan vuoden iällään myös vanhin – useimmat maailman järvet ovat vain jääkauden ikäisiä.", "Kapeaan hautavajoamaan kertynyt vesimassa tekee Baikalista myös tilavuudeltaan maailman suurimman makean veden järven."]}, {"h": "Amerikan ja Afrikan jättiläiset", "p": ["Pinta-alaltaan suurin makean veden järvi on Pohjois-Amerikan Yläjärvi eli Lake Superior, noin 82 100 neliökilometriä. Se kuuluu viiden Ison järven ketjuun yhdessä Michiganin, Huronin, Erien ja Ontarion kanssa – kanadalainen Manitobajärvi ei ketjuun kuulu.", "Afrikan suurin on Victoriajärvi, noin 69 500 neliökilometriä eli makean veden järvistä toiseksi suurin. Se on samalla Niilin tärkein vesivarasto kolmen valtion rajalla."]}, {"h": "Euroopan suurimmat ja Saimaa", "p": ["Euroopan suurin järvi on Venäjän Laatokka, noin 17 600 neliökilometriä. Pelkästään siinä on vettä lähes neljä kertaa niin paljon kuin kaikissa Suomen järvissä yhteensä.", "Suomen suurin, Saimaa, on kokonaisuutena noin 4 400 neliökilometriä ja lukeutuu Euroopan suurimpiin järviin. Sen tunnetuin asukas on saimaannorppa, jonka kanta on kasvanut jo yli 500 yksilöön."]}, {"h": "Korkealla ja matalalla", "p": ["Korkeuden ennätystä pitää Titicacajärvi Perun ja Bolivian rajalla: noin 8 300 neliökilometrin allas 3 810 metrin korkeudessa on maailman korkein suurille aluksille purjehduskelpoinen järvi.", "Vastakkaista ääripäätä edustaa Kuollutmeri, jonka rannalla sijaitsee maapallon matalin kohta kuivalla maalla, yli 400 metriä merenpinnan alapuolella. Suolaisen järven pinta laskee yhä vuosi vuodelta."]}], "faq": [{"q": "Onko Kaspianmeri järvi vai meri?", "a": "Se on maailman suurin sisävesi: suolainen mutta vailla yhteyttä valtameriin, joten vertailuissa se luetaan järveksi."}, {"q": "Missä järvessä on eniten vettä?", "a": "Baikaljärvessä, joka on tilavuudeltaan maailman suurin makean veden järvi. Pinta-alaltaan suurin makeavesijärvi on Yläjärvi."}, {"q": "Mitkä ovat Pohjois-Amerikan Isot järvet?", "a": "Yläjärvi, Michigan, Huron, Erie ja Ontario. Esimerkiksi Manitobajärvi ei kuulu joukkoon."}, {"q": "Kuinka suuri Saimaa on kansainvälisessä vertailussa?", "a": "Kokonaisuutena noin 4 400 km², millä se lukeutuu Euroopan suurimpiin järviin heti Laatokan, Äänisen ja Vänernin jälkeen."}], "sources": [{"name": "NASA Earth Observatory: The Caspian Sea's Shrinking Coastline", "url": "https://science.nasa.gov/earth/earth-observatory/the-caspian-seas-shrinking-coastline/"}, {"name": "Britannica: Lake Baikal", "url": "https://www.britannica.com/place/Lake-Baikal"}, {"name": "Britannica: Lake Victoria", "url": "https://www.britannica.com/place/Lake-Victoria"}, {"name": "Britannica: Lake Ladoga", "url": "https://www.britannica.com/place/Lake-Ladoga"}, {"name": "National Museum of the Great Lakes: Lake Superior", "url": "https://nmgl.org/lake-superior/"}], "last_reviewed": "2026-08-02"}$LJ$::jsonb where slug = 'maailman-suurimmat-jarvet';
update quizzes set learn = $LJ${"intro": "Kahdeksan kilometrin korkeudessa happea on vain kolmannes merenpinnan tasosta, ja silti huippujonot kasvavat joka kevät. Korkeimpien vuorten lista näyttää yksinkertaiselta, mutta järjestys riippuu yllättävän paljon siitä, mistä kohtaa mittanauha vedetään.", "heading": "Nyt tiedät nämä maailman korkeimmista vuorista", "key_facts": [{"k": "Kuinka korkea Mount Everest on virallisesti?", "v": "Nepal ja Kiina julkistivat joulukuussa 2020 yhteisen mittaustuloksen: 8 848,86 metriä eli pyöristettynä 8 849 metriä.", "qi": 1}, {"k": "Miksi Mauna Kea on korkein tyveltä huipulle mitattuna?", "v": "Havaijin Mauna Kea kohoaa Tyynenmeren pohjasta yli 10 200 metriä, vaikka merenpinnan yläpuolella siitä näkyy vain noin 4 200 metriä.", "qi": 2}, {"k": "Mistä K2 sai lempinimensä Savage Mountain?", "v": "Poikkeuksellisesta vaarallisuudestaan. K2 oli viimeinen kahdeksantonninen, joka huiputettiin talvella — nepalilaisryhmä onnistui siinä vasta tammikuussa 2021.", "qi": 3}, {"k": "Mikä vuorenhuippu on kauimpana Maan keskipisteestä?", "v": "Ecuadorin Chimborazo, koska Maa pullistuu päiväntasaajalla. Sen huippu on yli kaksi kilometriä kauempana Maan keskipisteestä kuin Everestin.", "qi": 5}, {"k": "Mikä on Euroopan korkein vuori?", "v": "Kaukasuksen Elbrus, 5 642 metriä. Alppien Mont Blanc (4 810 m) jää kakkoseksi, joskin Euroopan ja Aasian rajanvedosta kiistellään yhä.", "qi": 6}, {"k": "Missä on maailman korkein vuorenseinämä?", "v": "Nanga Parbatin Rupal-seinämä Pakistanissa nousee laakson pohjalta noin 4 600 metriä.", "qi": 8}, {"k": "Millä mantereella maailman sata korkeinta vuorta ovat?", "v": "Kaikki Aasiassa, Himalajan ja sen naapurivuoristojen alueella. Siksi Etelä-Amerikan korkein Aconcagua ei mahdu edes kymmenen kärkeen.", "qi": 9}], "title": "Maailman korkeimmat vuoret pähkinänkuoressa", "sections": [{"h": "Himalajan jättiläiset", "p": ["Maailman korkeimpien vuorten lista on käytännössä Aasian karttaharjoitus: sata korkeinta huippua sijaitsevat kaikki Himalajalla ja sen naapurivuoristoissa. Ne syntyivät, kun Intian mannerlaatta törmäsi Euraasian laattaan kymmeniä miljoonia vuosia sitten — ja koska törmäys jatkuu yhä, vuoristo nousee edelleen hitaasti.", "Mount Everestin virallinen korkeus, 8 848,86 metriä, on Nepalin ja Kiinan joulukuussa 2020 yhdessä julkistama tulos. Kolmanneksi korkein Kangchenjunga (8 586 m) ehti 1800-luvun puoliväliin asti kulkea papereissa maailman korkeimpana, kunnes Intian suuri kolmiomittaus paljasti todellisen järjestyksen."]}, {"h": "Kaikki riippuu mittaustavasta", "p": ["Everest on korkein merenpinnasta mitattuna, mutta muillakin on perusteltu vaatimus tittelistä. Havaijin Mauna Kea kohoaa tyveltään merenpohjasta yli 10 200 metriä ja on siten maailman korkein vuori tyveltä huipulle mitattuna — merenpinnan yläpuolelle siitä yltää vain reilut 4 200 metriä.", "Ecuadorin Chimborazon huippu taas on kauimpana Maan keskipisteestä. Koska planeettamme pullistuu päiväntasaajalla, Chimborazon huippu on yli kaksi kilometriä kauempana keskipisteestä kuin Everestin."]}, {"h": "Savage Mountain ja lempeämmät kahdeksantonniset", "p": ["K2, maailman toiseksi korkein vuori, tunnetaan lempinimellä Savage Mountain vaarallisuutensa vuoksi. Se oli viimeinen yli 8 000 metrin huippu ilman talvinousua, kunnes nepalilainen kiipeilijäryhmä teki historiaa tammikuussa 2021.", "Toisessa ääripäässä on Cho Oyu, jota pidetään yleisesti helpoimpana kahdeksantonnisena — sen kupeessa kulkee vanha kauppareitti Nepalin ja Tiibetin välillä. Pakistanin Nanga Parbat puolestaan komeilee tilastoissa Rupal-seinämällään, joka nousee noin 4 600 metriä ja on maailman korkein vuorenseinämä."]}, {"h": "Euroopan katolla", "p": ["Euroopan korkeimman vuoren tittelistä väitellään yhä. Useimmat lähteet antavat sen Kaukasuksella sijaitsevalle Elbrukselle (5 642 m), joka jää yleisimmin käytetyn Euroopan ja Aasian rajalinjan eurooppalaiselle puolelle. Jos raja vedetään toisin, ykköseksi nousee Alppien Mont Blanc (4 810 m).", "Etelä-Amerikan Aconcagua on läntisen pallonpuoliskon korkein huippu, mutta vajaan 7 000 metrin korkeudellaan se ei yllä maailman kymmenen korkeimman joukkoon — sinne mahtuvat vain Aasian jättiläiset."]}], "faq": [{"q": "Kuinka monta yli 8 000 metrin vuorta maailmassa on?", "a": "Neljätoista, ja ne kaikki sijaitsevat Himalajalla ja Karakorumissa Aasiassa."}, {"q": "Missä maissa Mount Everest sijaitsee?", "a": "Everestin huippu on Nepalin ja Kiinan (Tiibetin) rajalla, ja vuorelle kiivetään molemmilta puolilta."}, {"q": "Mikä on maailman toiseksi korkein vuori?", "a": "K2 Karakorumin vuoristossa Pakistanin ja Kiinan rajalla, 8 611 metriä."}, {"q": "Kasvaako Mount Everest yhä?", "a": "Kyllä — mannerlaattojen törmäys nostaa Himalajaa edelleen muutamia millimetrejä vuodessa, joskin eroosio syö osan noususta."}], "sources": [{"name": "Britannica: Mount Everest", "url": "https://www.britannica.com/place/Mount-Everest"}, {"name": "NOAA Ocean Service: What is the highest point on Earth?", "url": "https://oceanservice.noaa.gov/facts/highestpoint.html"}, {"name": "Britannica: Kanchenjunga", "url": "https://www.britannica.com/place/Kanchenjunga"}, {"name": "ExplorersWeb: The First Winter Ascent of K2", "url": "https://explorersweb.com/top-10-expeditions-of-2021-2-the-first-winter-ascent-of-k2/"}, {"name": "Guinness World Records: Tallest mountain", "url": "https://www.guinnessworldrecords.com/world-records/tallest-mountain"}], "last_reviewed": "2026-08-02"}$LJ$::jsonb where slug = 'maailman-korkeimmat-vuoret-visa';
update quizzes set learn = $LJ${"intro": "Joet ovat rakentaneet sivilisaatioita, kuljettaneet kauppaa ja uurtaneet kanjoneita miljoonien vuosien ajan. Silti edes maailman pisimmän joen tittelistä ei olla yksimielisiä, sillä tulos riippuu siitä, mistä latvahaarasta mittaaminen aloitetaan.", "heading": "Nyt tiedät nämä maailman pisimmistä joista", "key_facts": [{"k": "Kuinka pitkä Niili on?", "v": "Yleisimmin käytetty luku on noin 6 650 kilometriä, mikä tekee siitä useimpien mittausten mukaan maailman pisimmän joen.", "qi": 1}, {"k": "Mikä on Euroopan pisin joki?", "v": "Volga, noin 3 530 kilometriä. Se virtaa kokonaan Venäjän alueella ja laskee Kaspianmereen.", "qi": 2}, {"k": "Kuinka syvä maailman syvin joki on?", "v": "Kongojoesta on mitattu noin 220 metrin syvyyksiä — enemmän kuin mistään muusta joesta maailmassa.", "qi": 3}, {"k": "Minne Pariisin halki virtaava Seine laskee?", "v": "Noin 780 kilometrin pituinen Seine laskee Englannin kanaaliin Le Havren kohdalla.", "qi": 4}, {"k": "Kuinka monen maan läpi Tonava virtaa?", "v": "Kymmenen — enemmän kuin mikään muu joki. Sen varrella on myös neljä pääkaupunkia: Wien, Bratislava, Budapest ja Belgrad.", "qi": 5}, {"k": "Mikä on Aasian pisin joki?", "v": "Jangtse, noin 6 300 kilometriä. Se on koko maailman kolmanneksi pisin ja virtaa alusta loppuun Kiinassa.", "qi": 7}, {"k": "Miksi Coloradojoen vesi ei aina yllä mereen?", "v": "Grand Canyonin uurtanut joki valjastetaan niin tarkkaan kasteluun ja kaupunkien käyttöön, että se ehtyy useimpina vuosina ennen Kalifornianlahtea.", "qi": 9}], "title": "Maailman pisimmät joet pähkinänkuoressa", "sections": [{"h": "Niili, Amazon ja ikuinen kiista", "p": ["Niili on perinteisesti maailman pisin joki: yleisimmin käytetty pituus on noin 6 650 kilometriä sen kaukaisimmilta latvavesiltä Välimereen. Amazonille annetaan tavallisesti noin 6 400 kilometriä, mutta osa tutkijoista laskee sen pidemmäksi valitsemalla eteläisemmän lähtöpisteen Perun Andeilta.", "Kiista ei ratkea helposti, sillä joen alkupisteen määrittely on osin sopimuskysymys. Vesimäärässä Amazon on kuitenkin ylivoimainen: se kuljettaa mereen enemmän vettä kuin mikään muu joki maailmassa."]}, {"h": "Euroopan valtasuonet", "p": ["Euroopan pisin joki on Volga, noin 3 530 kilometriä. Se virtaa kokonaan Venäjällä ja laskee sisämereen, Kaspianmereen. Tonava taas on jokien kosmopoliitti: se koskettaa kymmentä valtiota — enemmän kuin mikään muu joki — ja sen rannoilla ovat pääkaupungeista Wien, Bratislava, Budapest ja Belgrad.", "Ranskan Seine on näihin verrattuna lyhyt, noin 780 kilometriä, mutta harva joki on kulttuurihistoriallisesti tunnetumpi. Pariisin halki virrattuaan se laskee Englannin kanaaliin Le Havren satamakaupungin kohdalla."]}, {"h": "Aasian ja Afrikan jättiläiset", "p": ["Aasian pisin joki on Jangtse, noin 6 300 kilometriä ja koko maailman kolmossija. Se virtaa alusta loppuun Kiinassa. Kaakkois-Aasian halki kiemurteleva Mekong taas ruokkii kymmeniä miljoonia ihmisiä Tiibetin ylängöltä Vietnamin suistoon asti.", "Afrikassa on pituustilaston kärjen lisäksi myös syvyysennätys: Kongojoen alajuoksulta on mitattu noin 220 metrin syvyyksiä, enemmän kuin mistään muusta joesta. Niilin ja Kongon ohella maanosan suuria jokia ovat muun muassa Niger, Sambesi ja Oranje."]}, {"h": "Pohjois-Amerikan suuret virrat", "p": ["Mississippi laskee Meksikonlahteen New Orleansin eteläpuolella. Yhdessä Missouri-haaransa kanssa se muodostaa Pohjois-Amerikan pisimmän jokisysteemin.", "Coloradojoki on uurtanut Grand Canyonia miljoonien vuosien ajan. Noin 2 330 kilometrin pituisen joen vesi käytetään nykyään niin tarkkaan maatalouden ja kaupunkien tarpeisiin, ettei virta useimpina vuosina enää yllä Kalifornianlahteen saakka."]}], "faq": [{"q": "Mikä on maailman pisin joki?", "a": "Useimpien mittausten mukaan Niili, noin 6 650 kilometriä. Osa tutkijoista pitää Amazonia pidempänä, sillä tulos riippuu siitä, mikä latvahaara valitaan lähtöpisteeksi."}, {"q": "Mikä on maailman vesirikkain joki?", "a": "Amazon — sen virtaama on ylivoimaisesti maailman suurin."}, {"q": "Mihin mereen Volga laskee?", "a": "Kaspianmereen, joka on maailman suurin sisävesiallas."}, {"q": "Mikä on Pohjois-Amerikan pisin jokisysteemi?", "a": "Mississippi–Missouri-jokisysteemi, joka kokoaa vedet suurelta osalta Yhdysvaltoja ja laskee Meksikonlahteen."}], "sources": [{"name": "Britannica: How Long Is the Amazon River?", "url": "https://www.britannica.com/story/how-long-is-the-amazon-river"}, {"name": "Britannica: Volga River", "url": "https://www.britannica.com/place/Volga-River"}, {"name": "Britannica: Danube River", "url": "https://www.britannica.com/place/Danube-River"}, {"name": "Britannica: Yangtze River", "url": "https://www.britannica.com/place/Yangtze-River"}, {"name": "Live Science: The Congo River Basin, home of the deepest river in the world", "url": "https://www.livescience.com/congo-river.html"}], "last_reviewed": "2026-08-02"}$LJ$::jsonb where slug = 'maailman-pisimmat-joet';
update quizzes set learn = $LJ${"intro": "Pakkanen kirpaisee suomalaisillekin tutulla tavalla, mutta maapallon kylmimmissä kolkissa eletään arkea lukemissa, joissa autoja ei uskalleta sammuttaa koko talvena ja silmäripset huurtuvat sekunneissa. Kylmyys sanelee siellä kaiken rakentamisesta koulupäiviin.", "heading": "Nyt tiedät nämä maailman kylmimmistä kolkista", "key_facts": [{"k": "Mikä on kylmin koskaan mitattu lämpötila?", "v": "-89,2 °C, mitattu Vostokin tutkimusasemalla Etelämantereella heinäkuussa 1983. Lukema on yhä WMO:n vahvistama maailmanennätys.", "qi": 0}, {"k": "Missä on maailman kylmin pysyvästi asuttu paikka?", "v": "Oimjakonin kylässä Venäjän Sahan tasavallassa, jossa on mitattu -67,8 °C. Kylässä asutaan ja käydään koulua ympäri vuoden.", "qi": 1}, {"k": "Missä Suomen pakkasennätys mitattiin?", "v": "Kittilän Pokassa tammikuussa 1999: -51,5 °C. Ruotsin ennätys on tätäkin hieman kylmempi.", "qi": 2}, {"k": "Kenelle Etelämanner kuuluu?", "v": "Ei millekään valtiolle. Vuonna 1959 solmittu Etelämanner-sopimus jäädytti aluevaatimukset ja varasi mantereen rauhanomaiseen tutkimuskäyttöön.", "qi": 4}, {"k": "Mikä on maailman kylmin suurkaupunki?", "v": "Siperian Jakutsk, jossa yli 40 asteen pakkaset ovat talvisin arkipäivää ja pohjalukemat ovat käyneet yli 60 asteessa.", "qi": 6}, {"k": "Mitä Pohjoisnavan jään alla on?", "v": "Pelkkää valtamerta: napajää on kelluvaa merijäätä. Etelänapa sen sijaan sijaitsee mantereen ja paksun jäätikön päällä.", "qi": 7}, {"k": "Miksi Siperian talot seisovat tolppien päällä?", "v": "Jotta rakennuksen lämpö ei sulattaisi alla olevaa ikiroutaa. Sulava maa vajoaa ja halkaisisi suoraan maahan perustetun talon.", "qi": 9}], "title": "Maailman kylmimmät kolkat pähkinänkuoressa", "sections": [{"h": "Etelämanner — kylmyyden omassa sarjassaan", "p": ["Maapallon kylmin koskaan mitattu lämpötila, -89,2 °C, kirjattiin Neuvostoliiton Vostokin tutkimusasemalla Etelämantereella heinäkuussa 1983. Kylmyyttä selittää paksu mannerjäätikkö: asema sijaitsee yli kolmen kilometrin korkeudessa jään päällä, kaukana merten lauhduttavasta vaikutuksesta.", "Etelämanner ei kuulu millekään valtiolle. Vuonna 1959 solmittu Etelämanner-sopimus jäädytti valtioiden aluevaatimukset ja varasi koko mantereen rauhanomaiselle tutkimukselle — järjestely, joka pitää yhä."]}, {"h": "Siperia — pakkasen asuttu ääripää", "p": ["Kylmin pysyvästi asuttu paikka on Oimjakonin kylä Venäjän Sahan tasavallassa, jossa on mitattu -67,8 astetta. Saman alueen pääkaupunki Jakutsk on maailman kylmin suurkaupunki: yli 40 asteen pakkaset kuuluvat siellä tavalliseen talveen.", "Ikirouta sanelee rakentamisen. Talot nostetaan tolppien varaan, jotta rakennuksen lämpö ei sulattaisi jäistä maata alta — sulava maa vajoaa ja halkoo suoraan maahan perustettuja rakennuksia. Ilmaston lämmetessä ikiroudan sulaminen on alkanut vaurioittaa taloja ja teitä eri puolilla Siperiaa."]}, {"h": "Pohjoisnapa on merta, etelänapa mannerta", "p": ["Pohjoisnavan jään alla ei ole maata vaan Pohjoinen jäämeri, ja napajää on kelluvaa merijäätä. Meri lauhduttaa arktista aluetta, minkä vuoksi se on Etelämannerta leudompi. Jääkarhut elävät vain pohjoisilla napa-alueilla ja pingviinit vain eteläisellä pallonpuoliskolla — luonnossa ne eivät koskaan kohtaa.", "Pohjoisin pysyvästi asutettu paikka on Kanadan Alert Ellesmerensaarella, noin 800 kilometrin päässä pohjoisnavasta. Islannin Reykjavik taas jää yllättäen napapiirin eteläpuolelle, noin 64. leveysasteelle."]}, {"h": "Pohjolan omat ennätykset", "p": ["Suomen pakkasennätys -51,5 °C mitattiin Kittilän Pokassa tammikuussa 1999. Ruotsin ennätys on hieman kylmempi, ja koko Pohjolan kylmimmät viralliset lukemat painuvat lähelle -53:a astetta.", "Kylmyys ei silti estä elämää: napapiirin pohjoispuolella asuu satojatuhansia ihmisiä, ja Venäjän Murmansk on napapiirin pohjoispuolisista kaupungeista suurin."]}], "faq": [{"q": "Mikä on kylmin paikka, jossa ihmiset asuvat pysyvästi?", "a": "Oimjakonin kylä Venäjän Sahan tasavallassa, jossa on mitattu -67,8 °C."}, {"q": "Miksi Etelämanner on kylmempi kuin pohjoinen napa-alue?", "a": "Etelänapa sijaitsee korkean mannerjäätikön päällä kaukana merestä, kun taas Pohjoisnavan alla oleva valtameri lauhduttaa ilmastoa."}, {"q": "Näkeekö jääkarhuja ja pingviinejä samassa paikassa?", "a": "Ei luonnossa: jääkarhut elävät vain arktisella alueella pohjoisessa ja pingviinit vain eteläisellä pallonpuoliskolla."}, {"q": "Onko Suomessa ikiroutaa?", "a": "Vain vähän: sitä esiintyy lähinnä Pohjois-Lapin palsasoiden turvekummuissa ja paikoin tuntureiden lakialueilla."}], "sources": [{"name": "WMO: World Weather & Climate Extremes Archive", "url": "https://wmo.int/asu-map?map=Temp_020"}, {"name": "Britannica: Vostok Station", "url": "https://www.britannica.com/place/Vostok-Station"}, {"name": "Ilmatieteen laitos: Kovat pakkaset ja kylmimmät talvet", "url": "https://www.ilmatieteenlaitos.fi/kovat-pakkaset-ja-kylmimmat-talvet"}, {"name": "Yle Elävä arkisto: Suomen pakkasennätys rikottiin Kittilässä 1999", "url": "https://yle.fi/a/20-106271"}, {"name": "Etelämanner-sopimuksen sihteeristö: The Antarctic Treaty", "url": "https://www.ats.aq/e/antarctictreaty.html"}], "last_reviewed": "2026-08-02"}$LJ$::jsonb where slug = 'maailman-kylmimmat-kolkat';
update quizzes set learn = $LJ${"intro": "Roomassa kävelet kirjaimellisesti historian päällä: katukiveyksen alla lepää kerroksittain antiikin temppeleitä, varhaiskristillisiä kirkkoja ja renessanssipalatsien perustuksia. Kaupunki on ollut tasavallan, keisarikunnan ja katolisen kirkon keskus, ja jokainen aikakausi jätti jälkensä katukuvaan.", "heading": "Nyt tiedät nämä Roomasta", "key_facts": [{"k": "Millä joella Rooma sijaitsee?", "v": "Rooma rakentui Tiberin rannoille noin 24 kilometrin päähän Välimerestä. Joen ylityspaikka teki paikasta luontevan kauppapaikan jo ennen kaupungin syntyä.", "qi": 0}, {"k": "Milloin Colosseum vihittiin käyttöön?", "v": "Keisari Vespasianus aloitti rakennustyöt noin vuonna 70, ja hänen poikansa Titus vihki amfiteatterin vuonna 80 jaa. Katsomoon mahtui noin 50 000 katsojaa.", "qi": 1}, {"k": "Kuka perusti Rooman legendan mukaan?", "v": "Tarun mukaan naarassuden imettämä Romulus perusti kaupungin 21. huhtikuuta 753 eaa. surmattuaan kaksoisveljensä Remuksen.", "qi": 2}, {"k": "Missä Pietarinkirkko sijaitsee?", "v": "Pietarinkirkko kohoaa Vatikaanissa, maailman pienimmässä valtiossa Rooman sisällä. Yli sata vuotta rakennettu basilika on maailman suurimpia kirkkoja, ja sen kupolin suunnitteli Michelangelo.", "qi": 3}, {"k": "Mikä YK-järjestö toimii Roomassa?", "v": "YK:n elintarvike- ja maatalousjärjestö FAO:n päämaja sijaitsee Roomassa Circus Maximuksen tuntumassa.", "qi": 5}, {"k": "Mitä S.P.Q.R. tarkoittaa?", "v": "Lyhenne tulee sanoista Senatus Populusque Romanus, 'senaatti ja Rooman kansa'. Se koristaa yhä kaupungin vaakunaa ja jopa katukaivojen kansia.", "qi": 8}, {"k": "Mikä on Rooman vanhin yliopisto?", "v": "La Sapienza perustettiin jo vuonna 1303, ja nykyisin se on Euroopan suurimpia yliopistoja.", "qi": 9}], "title": "Rooma pähkinänkuoressa", "sections": [{"h": "Susilegendasta maailmanvallaksi", "p": ["Legendan mukaan Romulus perusti Rooman Palatinus-kukkulalle 21. huhtikuuta 753 eaa. surmattuaan kaksoisveljensä Remuksen. Tarun kaksoset kasvatti naarassusi, joka on yhä kaupungin tunnus. Arkeologia kertoo maltillisemman version: kukkuloille syntyi paimenkyliä, jotka kasvoivat yhteen Tiberin ylityspaikan äärellä.", "Kuningasajan ja tasavallan kautta Rooma paisui imperiumiksi, joka ulottui laajimmillaan Britanniasta Lähi-itään. Tasavallan tunnus S.P.Q.R. – senaatti ja Rooman kansa – näkyy kaupungissa yhä kaikkialla, vaakunasta katukaivojen kansiin."]}, {"h": "Nähtävyydet, jotka jokainen tunnistaa", "p": ["Colosseum on antiikin Rooman kuuluisin muistomerkki. Vespasianus aloitti rakennustyöt noin vuonna 70, ja hänen poikansa Titus vihki amfiteatterin vuonna 80 sadan päivän kisoilla. Noin 50 000 katsojaa seurasi gladiaattoritaisteluja ja eläinnäytöksiä.", "Colosseumin naapurissa levittäytyy Forum Romanum, antiikin Rooman poliittinen sydän. Pantheonin betonikupoli on kestänyt lähes kaksi vuosituhatta, ja Trevin suihkulähteeseen heitetty kolikko lupaa perinteen mukaan paluun kaupunkiin."]}, {"h": "Vatikaani – valtio kaupungin sisällä", "p": ["Rooman kupeessa sijaitsee maailman pienin itsenäinen valtio, Vatikaani. Sen sydän on Pietarinkirkko, jonka rakentaminen alkoi 1506 ja kesti yli sata vuotta. Michelangelon suunnittelema kupoli hallitsee yhä kaupungin siluettia.", "Pietarinkirkon lisäksi vierailijaa odottavat Vatikaanin museot ja Sikstuksen kappelin freskot – syy, miksi jonot alkavat kertyä jo aamuvarhaisella."]}, {"h": "Yllättävää Roomasta", "p": ["Rooma on myös YK-kaupunki: elintarvike- ja maatalousjärjestö FAO:n päämaja sijaitsee Circus Maximuksen kupeessa. Kesällä 1960 kaupunki isännöi olympialaisia, joiden maraton juostiin soihtujen valaisemalla Via Appialla antiikin raunioiden lomassa.", "Kaupungin vanhin yliopisto La Sapienza perustettiin jo 1303. Tuoreempaa historiaa edustaa 4. kesäkuuta 1944, jolloin liittoutuneet vapauttivat Rooman ensimmäisenä akselivaltojen pääkaupungeista."]}, {"h": "Ikuinen kaupunki tänään", "p": ["Nykyroomassa asuu noin 2,8 miljoonaa ihmistä, mikä tekee siitä Italian suurimman kaupungin. Tiber halkoo kaupunkia, ja sen rannoilta nousevat niin antiikin rauniot kuin Trasteveren trattoriat.", "Vierailijalle Rooma aukeaa parhaiten kävellen: keskustan nähtävyydet ovat lähellä toisiaan, ja lähes jokaisen kulman takaa löytyy suihkulähde, aukio tai kirkko, jonka takana on barokin mestareiden kädenjälki."]}], "faq": [{"q": "Miksi Roomaa kutsutaan ikuiseksi kaupungiksi?", "a": "Nimitys Roma Aeterna juontaa antiikin runoilijoilta, jotka uskoivat Rooman kestävän ikuisesti. Lähes kolmen vuosituhannen yhtäjaksoinen historia on pitänyt nimen elossa."}, {"q": "Onko Vatikaani osa Roomaa?", "a": "Ei – Vatikaani on itsenäinen valtio Rooman sisällä. Käytännössä rajan ylittää huomaamattaan kävellessään Pietarinaukiolle."}, {"q": "Kuinka monta päivää Roomaan kannattaa varata?", "a": "Kolmessa päivässä ehtii tärkeimmät: antiikin Rooman, Vatikaanin ja keskustan aukiot. Viikossakaan kaupunki ei lopu kesken."}, {"q": "Milloin Roomassa kannattaa vierailla?", "a": "Kevät ja syksy ovat miellyttävimmät vuodenajat: heinä–elokuussa helle voi olla tukala ja suosituimmilla kohteilla on pisimmät jonot."}], "sources": [{"name": "Encyclopaedia Britannica – Rome", "url": "https://www.britannica.com/place/Rome"}, {"name": "Encyclopaedia Britannica – St. Peter's Basilica", "url": "https://www.britannica.com/topic/Saint-Peters-Basilica"}, {"name": "Turismo Roma – The Flavian Amphitheatre (The Colosseum)", "url": "https://www.turismoroma.it/en/places/flavian-amphitheatre-colosseum"}, {"name": "FAO – A short history", "url": "https://www.fao.org/UNFAO/histo-e.htm"}], "last_reviewed": "2026-08-02"}$LJ$::jsonb where slug = 'rooma-ikuinen-kaupunki';
update quizzes set learn = $LJ${"intro": "Lontoossa kuninkaallinen seremonia ja maailman finanssikauppa toimivat saman joen varrella, ja punaiset kaksikerrosbussit sujahtavat ohi lähes kaksituhatvuotisten muurinjäänteiden. Roomalaisesta kauppapaikasta kasvoi metropoli, jossa käytännössä koko maailma on edustettuna.", "heading": "Nyt tiedät nämä Lontoosta", "key_facts": [{"k": "Mikä joki virtaa Lontoon läpi?", "v": "Thames halkoo koko kaupungin ja laskee Pohjanmereen. Joki teki Lontoosta satamakaupungin ja maailmankaupan keskuksen.", "qi": 0}, {"k": "Montako kertaa Lontoo on isännöinyt kesäolympialaiset?", "v": "Kolmesti – vuosina 1908, 1948 ja 2012. Lontoo oli ensimmäinen kaupunki, joka sai kisat kolmannen kerran.", "qi": 1}, {"k": "Minä vuonna Lontoon suurpalo riehui?", "v": "Vuoden 1666 suurpalo tuhosi valtaosan keskiaikaisesta kaupungista. Jälleenrakennus tuotti muun muassa Christopher Wrenin St Paulin katedraalin.", "qi": 3}, {"k": "Mikä oli Lontoon roomalainen nimi?", "v": "Roomalaiset perustivat Thamesin rannalle Londiniumin noin vuonna 43 jaa. Nykyinen City of London seisoo saman asutuksen paikalla.", "qi": 6}, {"k": "Missä West Endin teatterialue sijaitsee?", "v": "West End sijaitsee Westminsterin kaupunginosassa. Sen yli 40 teatteria tekevät siitä yhden maailman suurimmista teatterikeskittymistä.", "qi": 7}, {"k": "Montako kieltä Lontoossa puhutaan?", "v": "Yli 300 – Lontoo on yksi maailman monikielisimmistä kaupungeista.", "qi": 8}, {"k": "Mistä Arsenalin lempinimi The Gunners tulee?", "v": "'Tykkimiehet' juontuu seuran synnystä: sen perustivat Woolwichin asetehtaan työläiset 1800-luvun lopulla.", "qi": 9}], "title": "Lontoo pähkinänkuoressa", "sections": [{"h": "Londiniumista maailmankaupungiksi", "p": ["Roomalaiset perustivat Thamesin rannalle Londinium-nimisen kauppapaikan noin vuonna 43 jaa. Sillanpääasemasta kasvoi provinssin keskus, ja keskiajalla Lontoo nousi Englannin kaupan ja kuninkaanvallan sydämeksi.", "Vuoden 1666 suurpalo tuhosi valtaosan keskiaikaisesta kaupungista, mutta tuhkasta nousi Christopher Wrenin suunnittelema St Paulin katedraali. Imperiumin vuosisatoina Lontoosta tuli aikansa suurin kaupunki, ja sen jälki näkyy yhä museoiden kokoelmissa ja katujen nimissä."]}, {"h": "Ikoniset maamerkit", "p": ["Westminsterin parlamenttitalon kellotorni, jonka suurkelloa kutsutaan Big Beniksi, on kaupungin tunnetuin siluetti. Buckinghamin palatsin edessä seurataan vahdinvaihtoa, ja Towerin linnoituksessa vartioidaan kruununjalokiviä – sekä legendan mukaan korppeja, joiden lähtö ennustaisi kuningaskunnan tuhoa.", "Thames sitoo maamerkit yhteen: joki virtaa Tower Bridgen ali kohti Pohjanmerta, ja sen rannoilta nousevat niin London Eye kuin Shakespearen Globe-teatterin rekonstruktio."]}, {"h": "Teattereiden ja museoiden suurvalta", "p": ["Westminsterissä sijaitseva West End on yksi maailman suurimmista teatterialueista: yli 40 näyttämöä esittää musikaaleja ja draamaa joka ilta. Suurten museoiden, kuten British Museumin ja Tate Modernin, perusnäyttelyihin on vapaa pääsy.", "Jalkapallo on Lontoossa oma kulttuurinsa. Kaupungissa pelaa useita huippuseuroja, joista Arsenal tunnetaan lempinimellä The Gunners – muisto seuran juurista asetehtaan työläisjoukkueena."]}, {"h": "Yllättävää Lontoosta", "p": ["Lontoossa puhutaan yli 300 kieltä, mikä tekee siitä yhden maailman monikielisimmistä kaupungeista. Virallisesti 'City of London' on vain reilun neliömailin kokoinen ydin, jolla on oma perinteikäs pormestarinsa – koko metropolia johtaa erikseen valittava pormestari, vuodesta 2016 Sadiq Khan.", "Kaupungin metro on maailman vanhin: ensimmäinen linja avattiin höyryvetureiden voimin jo 1863. Nykyisin 'the Tube' kattaa 272 asemaa ja noin 400 kilometriä rataa."]}, {"h": "Lontoo tänään", "p": ["Maailmalle Lontoo avautuu viiden kansainvälisen lentokentän kautta: Heathrow, Gatwick, Stansted, Luton ja City Airport. Vuoden 2012 olympialaiset jättivät perinnöksi kokonaan uudistetun East Endin Stratfordin alueen.", "Noin yhdeksän miljoonan asukkaan metropoli on Euroopan tärkeimpiä finanssikeskuksia, mutta vierailijalle se on ennen kaikkea kaupunki, jossa kuninkaallinen seremonia, curryravintola ja punatiilinen pubi mahtuvat samalle korttelivälille."]}], "faq": [{"q": "Ovatko Lontoon museot ilmaisia?", "a": "Monien suurten museoiden, kuten British Museumin, National Galleryn ja Tate Modernin, perusnäyttelyt ovat maksuttomia. Erikoisnäyttelyt ovat yleensä maksullisia."}, {"q": "Mikä ero on City of Londonilla ja Lontoolla?", "a": "City of London on vain reilun neliömailin kokoinen historiallinen ydin ja finanssikeskus, jolla on oma hallintonsa. Arkipuheessa Lontoolla tarkoitetaan koko Greater Londonin metropolia."}, {"q": "Kuinka monta asukasta Lontoossa on?", "a": "Greater Londonin alueella asuu noin yhdeksän miljoonaa ihmistä, mikä tekee siitä Länsi-Euroopan suurimpia kaupunkeja."}, {"q": "Mikä on paras tapa liikkua Lontoossa?", "a": "Metro eli 'the Tube' ja lähijunat kattavat kaupungin tehokkaasti, ja maksuksi käy lähimaksukortti. Keskustassa moni matka taittuu nopeimmin kävellen."}], "sources": [{"name": "Visit London – 101 facts about London", "url": "https://www.visitlondon.com/blog/facts-about-london"}, {"name": "Encyclopaedia Britannica – London", "url": "https://www.britannica.com/place/London"}, {"name": "Wikipedia – London Underground", "url": "https://en.wikipedia.org/wiki/London_Underground"}, {"name": "Wikipedia – Mayor of London", "url": "https://en.wikipedia.org/wiki/Mayor_of_London"}], "last_reviewed": "2026-08-02"}$LJ$::jsonb where slug = 'tiedatko-lontoosta-kaiken';
update quizzes set learn = $LJ${"intro": "Suomenlahden etelärannalla kohoaa tornien ja punaisten kattojen kaupunki, jossa keskiaikainen muuri ympäröi yhtä Euroopan parhaiten säilyneistä vanhoistakaupungeista. Samalla Tallinna on digiyhteiskunnan edelläkävijä, jossa lähes kaikki asiointi hoituu verkossa.", "heading": "Nyt tiedät nämä Tallinnasta", "key_facts": [{"k": "Kuinka suuri kaupunki Tallinna on?", "v": "Tallinnassa asuu noin 460 000 ihmistä, eli se on selvästi Viron suurin kaupunki.", "qi": 0}, {"k": "Milloin vanhakaupunki pääsi Unescon listalle?", "v": "Vanhakaupunki hyväksyttiin Unescon maailmanperintöluetteloon vuonna 1997. Kokonaisuuteen kuuluvat Toompean yläkaupunki ja kauppiaiden alakaupunki.", "qi": 1}, {"k": "Mikä maailmankuulu ohjelmisto syntyi Tallinnassa?", "v": "Skype kehitettiin Tallinnassa, ja sen menestys sysäsi liikkeelle Viron startup-buumin – kaupunkia on kutsuttu Itämeren Piilaaksoksi.", "qi": 2}, {"k": "Millä nimellä Tallinna tunnettiin ennen vuotta 1918?", "v": "Kansainvälisesti kaupunki tunnettiin vuosisatojen ajan nimellä Reval, aina Viron itsenäistymiseen 1918 saakka.", "qi": 3}, {"k": "Milloin Tallinna liittyi Hansaliittoon?", "v": "Kaupungista tuli Hansaliiton pohjoisin jäsen vuonna 1285, mikä toi sille Itämeren kaupan vaurauden.", "qi": 7}, {"k": "Missä käytiin vuoden 1980 olympiapurjehdukset?", "v": "Moskovan kesäolympialaisten purjehduskilpailut käytiin Tallinnan Piritalla vuonna 1980.", "qi": 5}, {"k": "Milloin Tallinna oli Euroopan kulttuuripääkaupunki?", "v": "Vuonna 2011, yhdessä Turun kanssa.", "qi": 9}], "title": "Tallinna pähkinänkuoressa", "sections": [{"h": "Taanilaisten linnasta hansakaupungiksi", "p": ["Tallinnan tarina alkaa 1200-luvulta, jolloin Toompean kukkulalle rakennettiin linna. Kaupungin nimen arvellaan juontuvan sanoista 'taani linn', taanilaisten kaupunki. Vuonna 1285 kaupungista tuli Hansaliiton pohjoisin jäsen, ja Itämeren kauppa toi vaurauden, joka näkyy yhä kauppiastaloissa.", "Maailmalla kaupunki tunnettiin vuosisatojen ajan nimellä Reval – vasta Viron itsenäistyttyä 1918 Tallinna vakiintui myös kansainväliseksi nimeksi."]}, {"h": "Vanhakaupunki – keskiajan aikakapseli", "p": ["Tallinnan vanhakaupunki hyväksyttiin Unescon maailmanperintöluetteloon 1997 poikkeuksellisen hyvin säilyneenä keskiaikaisena kauppakaupunkina. Kokonaisuuteen kuuluvat sekä Toompean yläkaupunki että kauppiaiden alakaupunki muureineen ja torneineen.", "Raatihuoneentorin laidalla seisoo Pohjois-Euroopan vanhin raatihuone 1300-luvun alkupuolelta, ja kapeat kujat kantavat yhä keskiaikaisia nimiään. Kaupunki ei silti ole museo: torilla juhlitaan niin keskiaikapäiviä kuin joulumarkkinoita."]}, {"h": "Yllättävää Tallinnasta", "p": ["Kaupungin juomavettä on otettu Ülemiste-järvestä jo 1300-luvulta lähtien. Tarun mukaan järvessä asuva Ülemisten ukko kysyy vastaantulijalta, onko kaupunki jo valmis – väärä vastaus hukuttaisi Tallinnan, joten kaupunki ei koskaan 'valmistu'.", "Tallinnan 159,3 neliökilometrin pinta-alaan mahtuvat myös Ülemiste- ja Harku-järvet sekä Aegnan saari, ja hallinnollisesti kaupunki jakautuu kahdeksaan kaupunginosaan. Kesällä 1980 Pirita pääsi olympiakartalle, kun Moskovan kisojen purjehduskilpailut käytiin Tallinnan edustalla."]}, {"h": "Digitaalinen edelläkävijä", "p": ["Tallinnassa kehitetty Skype teki kaupungista käsitteen startup-maailmassa, ja sittemmin Viron pääkaupunki on kasvanut yhdeksi Euroopan vilkkaimmista teknologiakeskittymistä. Entiset teollisuusalueet, kuten Telliskiven luova kortteli ja Noblessnerin vanha telakka, ovat muuttuneet gallerioiden, ravintoloiden ja toimistojen kaupunginosiksi.", "Vuonna 2011 Tallinna toimi Euroopan kulttuuripääkaupunkina yhdessä Turun kanssa – sopiva parivaljakko kahdelle Itämeren rantakaupungille."]}, {"h": "Vierailijalle", "p": ["Helsingistä Tallinnaan pääsee lautalla noin kahdessa tunnissa, ja satamasta kävelee vanhaankaupunkiin vartissa. Noin 460 000 asukkaan kaupunki on kompakti: päivässä ehtii keskiaikaisilta muureilta merenrantaan ja trendikortteleihin.", "Parhaiten Tallinna palkitsee, kun sille antaa aikaa – Kalamajan puutaloalue, Piritan rantabulevardi ja Kadriorgin barokkipuisto jäävät päiväristeilijältä helposti näkemättä."]}], "faq": [{"q": "Kuinka kauan laivamatka Helsingistä Tallinnaan kestää?", "a": "Nopeimmat lautat ylittävät Suomenlahden noin kahdessa tunnissa, ja vuoroja on ympäri vuoden useita päivässä."}, {"q": "Miksi Tallinnaa kutsuttiin Revaliksi?", "a": "Reval oli kaupungin kansainvälinen nimi keskiajalta Viron itsenäistymiseen 1918 saakka. Nimi juontuu ympäröivän muinaismaakunnan, Rävalan, nimestä."}, {"q": "Riittääkö yksi päivä Tallinnassa?", "a": "Vanhankaupungin ehtii kiertää päivässä, mutta Kalamaja, Telliskivi ja Kadriorg palkitsevat yöpyjän."}, {"q": "Mitä valuuttaa Virossa käytetään?", "a": "Virossa on käytössä euro, joten suomalaisen ei tarvitse vaihtaa rahaa."}], "sources": [{"name": "UNESCO World Heritage – Historic Centre (Old Town) of Tallinn", "url": "https://whc.unesco.org/en/list/822/"}, {"name": "Visit Tallinn – Old Town", "url": "https://www.visittallinn.ee/eng/visitor/see-do/neighbourhoods/old-town"}, {"name": "Visit Estonia – Tallinn", "url": "https://visitestonia.com/en/where-to-go/tallinn"}, {"name": "Wikipedia – Tallinn", "url": "https://en.wikipedia.org/wiki/Tallinn"}], "last_reviewed": "2026-08-02"}$LJ$::jsonb where slug = 'tallinna-tietovisa';
